8	export const escapeHtml = (value: string): string =>
9	  value
10	    .replace(/&/g, '&amp;')
11	    .replace(/</g, '&lt;')
12	    .replace(/>/g, '&gt;')
13	    .replace(/"/g, '&quot;')
14	    .replace(/'/g, '&#39;');
