96	/**
97	 * Generates a complete HTML document structure for export.
98	 *
99	 * @param documentTitle - The title of the document (will be escaped)
100	 * @param editorHtmlWithLocalMedia - The HTML content from the editor
101	 * @param lang - The language code for the document (e.g., 'fr', 'en')
102	 * @returns A complete HTML5 document string
103	 */
104	export const generateHtmlDocument = (
105	  documentTitle: string,
106	  editorHtmlWithLocalMedia: string,
107	  lang: string,
108	): string => {
109	  return `<!DOCTYPE html>
110	  <html lang="${lang}">
111	    <head>
112	      <meta charset="utf-8" />
113	      <title>${escapeHtml(documentTitle)}</title>
114	      <link rel="stylesheet" href="styles.css">
115	    </head>
116	    <body>
117	      <main role="main">
118	  ${editorHtmlWithLocalMedia}
119	      </main>
120	    </body>
121	  </html>`;
122	};
